sys_script_client.script:
/**
 * 19-Show rent total
 *
 * Runs onChange of Start Date, End Date and Car. Once all three are populated
 * it alerts the total rent = car rent x number of rental days.
 */
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || isLoading === 'true') {
        return;
    }

    var startDate = g_form.getValue('start_date');
    var endDate = g_form.getValue('end_date');
    var carId = g_form.getValue('car');

    if (!startDate || !endDate || !carId) {
        return;
    }

    var startMs = parseFormDate(startDate);
    var endMs = parseFormDate(endDate);
    if (startMs === null || endMs === null) {
        return;
    }

    if (endMs < startMs) {
        g_form.addErrorMessage('End Date cannot be earlier than Start Date.');
        return;
    }

    var days = Math.round((endMs - startMs) / 86400000);
    if (days < 1) {
        days = 1;
    }

    g_form.getReference('car', function (carRecord) {
        if (!carRecord) {
            return;
        }

        var rent = parseCurrency(carRecord.rent);
        var total = rent * days;

        alert(
            'Rental summary\n\n' +
                'Car: ' + carRecord.name + '\n' +
                'Rent per day: ' + rent.toFixed(2) + '\n' +
                'Rental days: ' + days + '\n' +
                'Total rent: ' + total.toFixed(2)
        );
    });

    /**
     * Converts a form date value into milliseconds. Uses the user's date format
     * first and falls back to the internal yyyy-MM-dd format.
     */
    function parseFormDate(value) {
        var ms = null;

        if (typeof getDateFromFormat === 'function' && typeof g_user_date_format !== 'undefined') {
            ms = getDateFromFormat(value, g_user_date_format);
        }

        if (!ms) {
            var parts = value.substring(0, 10).split('-');
            if (parts.length === 3) {
                ms = Date.UTC(
                    parseInt(parts[0], 10),
                    parseInt(parts[1], 10) - 1,
                    parseInt(parts[2], 10)
                );
            }
        }

        return isNaN(ms) || ms === null || ms === 0 ? null : ms;
    }

    /**
     * Currency fields are returned as "CUR;amount" - take the numeric part.
     */
    function parseCurrency(value) {
        var raw = value === null || typeof value === 'undefined' ? '' : String(value);
        var parts = raw.split(';');
        var amount = parseFloat(parts[parts.length - 1]);
        return isNaN(amount) ? 0 : amount;
    }
}
